712	// 列表查询交错返回（竞态）回归
713	//
714	// 打开首页会触发第一次 GET /api/rooms；创建成功后 loadRooms 会再触发一次。
715	// 若第一次查询迟迟不返回，两次查询会同时在途。页面用递增序号保证：只有最近发起
716	// 的查询允许更新列表区域，较早查询后返回的结果一律忽略——无论它成功返回旧列表
717	// （哪怕是空列表）还是失败。
718	//
719	// 这些用例用请求拦截把指定查询挂起，精确控制两次查询的返回内容与先后次序：
720	//   A. 较晚查询先成功（原有房间 + 新房间），较早查询随后成功返回创建前的旧
721	//      列表：旧列表被忽略，新列表内容与次序保持；
722	//   B. 同 A，但创建前没有房间，较早查询返回空列表：新房间保留，空提示不重现；
723	//   C. 较晚查询先成功，较早查询随后失败：已显示的新列表保留，失败提示不上屏；
724	//   D. 较晚查询先失败，较早查询随后成功返回旧房间：失败提示保留，旧记录不得
725	//      冒充本次刷新成功，读取失败不得被解释成“没有房间”；创建成功是独立结果
726	//      （成功提示与编号、表单复位、按钮恢复、服务端确已保存），不被列表结果
727	//      改写；
728	//   E. 较早查询在较晚查询已发起但未返回时抢先完成（旧列表成功 / 失败两种）：
729	//      既不得抢先上屏，也不得抢先显示失败，页面最终由较晚查询的结果决定。
730	// 无交错基线（空列表、首次读取失败后由创建刷新恢复）放在本节末尾；打开即有
731	// 房间的正常展示由前面的用例覆盖——每个用例的 setupPage 都先断言了两条种子
732	// 房间按现有列含义正确渲染，创建成功后照常追加新记录。
733	
734	const EMPTY_TEXT = '还没有房间记录。';
735	const LIST_ERROR_TEXT = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
736	
737	const STALE_SEEDED_ROOMS = [JSON.parse(SEED_ALPHA), JSON.parse(SEED_BETA)];
738	
739	// gateRoomLists 打开拦截后，页面的每一次 GET /api/rooms 都会被挂起并生成一个
740	// gate；其余请求（页面、POST 创建）照常放行到真实服务。测试用 gate.succeed(rooms)
741	// / gate.fail() 决定该次查询的返回内容与时机，从而稳定复现交错返回。
742	function gateRoomLists(page) {
743	  const gates = [];
744	  // puppeteer 的请求对象本身不暴露完成事件，需在 page 上按请求引用对应。
745	  const doneWaiters = new Map();
746	  const markDone = (req) => {
747	    const waiter = doneWaiters.get(req);
748	    if (waiter) {
749	      doneWaiters.delete(req);
750	      waiter();
751	    }
752	  };
753	  page.on('requestfinished', markDone);
754	  page.on('requestfailed', markDone);
755	  page.on('request', (req) => {
756	    const isRoomList = req.method() === 'GET' && req.url().endsWith('/api/rooms');
757	    if (!isRoomList) {
758	      req.continue();
759	      return;
760	    }
761	    const delivered = new Promise((resolve) => doneWaiters.set(req, resolve));
762	    const gate = {
763	      index: gates.length,
764	      // 用指定房间列表作为本次查询的成功结果，并等待浏览器确实收完响应、
765	      // 页面的 Promise 链得到执行机会后再返回。
766	      async succeed(rooms) {
767	        req.respond({
768	          status: 200,
769	          contentType: 'application/json; charset=utf-8',
770	          body: JSON.stringify({ rooms }),
771	        });
772	        await delivered;
773	        await new Promise((resolve) => setTimeout(resolve, 50));
774	      },
775	      async fail() {
776	        req.respond({
777	          status: 500,
778	          contentType: 'application/json; charset=utf-8',
779	          body: JSON.stringify({ error: '模拟列表读取失败' }),
780	        });
781	        await delivered;
782	        await new Promise((resolve) => setTimeout(resolve, 50));
783	      },
784	    };
785	    gates.push(gate);
786	  });
787	  return {
788	    gates,
789	    async waitFor(count) {
790	      const deadline = Date.now() + 10000;
791	      while (gates.length < count) {
792	        if (Date.now() > deadline) {
793	          throw new Error(`等待第 ${count} 次房间列表查询超时（实际只发起 ${gates.length} 次）`);
794	        }
795	        await new Promise((resolve) => setTimeout(resolve, 15));
796	      }
797	    },
798	  };
799	}
