  await waitForMessageKind(page, 'ok');
  // 保留状态与规则相符：飞行棋已选、人数未选（可选择），不自动补成 2。
  // 等列表刷新完成（按钮随之恢复）后再比对完整表单状态。
  await waitForRowCount(page, 3);
