    capacityDisabled: false,
    turnSeconds: '60',
    submitDisabled: false,
  }, '切到五子棋后应保留自动固定的 2 人状态');

  // 再次提交直接以五子棋/2 人创建。
  const secondPromise = nextPostResponse(page);
  await page.click('#submit');
