  // 响应未到达”与“状态行（201）已收到、但正文没读完整”这两种情况。
  // 后者既不能当成成功（没有编号可展示），也不能说成失败（房间可能
  // 已经在服务端保存），因此读取正文失败时只做标记，交由后面按状态
  // 分支处理，不让它落到最外层的连接失败提示。
  return resp.text().then(
    function (text) {
      return { ok: resp.ok, status: resp.status, text: text, readFailed: false };
    },
    function () {
      return { ok: resp.ok, status: resp.status, text: '', readFailed: true };
    }
  );
}).then(function (result) {
  // 正文为空、读取中断或不是合法 JSON 时 data 为 null；合法 JSON 中
  // 不是对象（null、数组、字符串、数字等）同样不能作为创建结果。
  var data = null;
  if (!result.readFailed && result.text !== '') {
    try {
      var parsed = JSON.parse(result.text);
      if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) {
        data = parsed;
      }
    } catch (e) {
      data = null;
    }
  }

