function submit(payload) {
  submitting = true;
  submitBtn.disabled = true;

  // 点击提交瞬间四项的实际填写值快照。本次房间固定按 payload（即点击时
  // 的配置）创建；响应到达时再读一次当前值与之逐项比较。
  var submittedValues = readFormValues();

  fetch('/api/rooms', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  }).then(function (resp) {
    // 先把正文作为文本读完，再由页面自行解析：必须能区分“请求未送达/
    // 响应未到达”与“状态行（201）已收到、但正文没读完整”这两种情况。
    // 后者既不能当成成功（没有编号可展示），也不能说成失败（房间可能
    // 已经在服务端保存），因此读取正文失败时只做标记，交由后面按状态
    // 分支处理，不让它落到最外层的连接失败提示。
    return resp.text().then(
      function (text) {
        return { ok: resp.ok, status: resp.status, text: text, readFailed: false };
      },
      function () {
        return { ok: resp.ok, status: resp.status, text: '', readFailed: true };
      }
    );
  }).then(function (result) {
    // 正文为空、读取中断或不是合法 JSON 时 data 为 null；合法 JSON 中
    // 不是对象（null、数组、字符串、数字等）同样不能作为创建结果。
    var data = null;
    if (!result.readFailed && result.text !== '') {
      try {
        var parsed = JSON.parse(result.text);
        if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) {
          data = parsed;
        }
      } catch (e) {
        data = null;
      }
    }

    if (result.ok && result.status === 201) {
      // 已收到 201 却拿不到完整合法、带编号的创建结果：创建是否落库
      // 无法确认。明确提示用户房间可能已经保存、先刷新列表核对，再
      // 决定是否重新提交；不承诺失败、不显示（更不能猜测）编号、不
      // 复位表单、不自动刷新列表、不自动重发。表单四项保持此刻页面
      // 上的实际填写（含等待期间的修改、首尾空白与未填完的项），
      // 已有列表原样保留；按钮在 finally 中恢复可用。
      if (!data || !data.id) {
        showMessage('error', '创建结果未能确认：服务器已接受创建（HTTP 201），' +
          '但响应内容没有读完整或无法解析，无法取得房间编号，房间可能已经保存。' +
          '请先刷新页面查看房间列表，再决定是否需要重新提交。');
        return;
      }

      var okText = '房间已创建，编号：' + data.id;

      // 是否复位以页面当前实际填写值为准，与提交时快照逐项比较：
      // 四项全部一致（含等待期间改过又完整恢复）才恢复初始表单；
      // 任一项不同——哪怕只动了名称的首尾空白——都整体保留当前四项
      // 及其对应的人数选择状态，不能只留改过的项，也不能把其他项
      // 恢复成旧配置；内容没填完整同样原样保留、不自动补齐。
      var currentValues = readFormValues();
      var unchanged = currentValues.name === submittedValues.name &&
        currentValues.game === submittedValues.game &&
        currentValues.capacity === submittedValues.capacity &&
        currentValues.turnSeconds === submittedValues.turnSeconds;

      if (unchanged) {
        showMessage('ok', okText);
        resetForm();
      } else {
        // 本次房间已按提交时的配置创建并生成编号；表单中是等待期间
        // 继续填写、尚未提交的新配置，不会自动创建下一间房，完整保留
        // 供用户处理完成后直接再次提交。
        showMessage('ok', okText + '。表单中当前填写的内容尚未提交，不会自动创建房间；' +
          '如需创建下一间，可直接点击“创建房间”。');
      }
      return loadRooms();
    }
    // 创建失败（被服务拒绝）：不触碰表单，等待期间的最新填写原样保留，
    // 不回退到提交时的值，仅显示服务给出的原因。正文无法读取或解析、
    // 或没有可读取的原因时，沿用现有的 HTTP 状态兜底文案（201 正文
    // 不完整这一特殊情况已在上面单独处理，不会走到这里）。
    var reason = data && data.error ? data.error
               : ('创建失败（HTTP ' + result.status + '）');
    showMessage('error', reason);
  }).catch(function () {
    // 连接失败同样保留当时最新的填写内容。
    showMessage('error', '无法连接服务，请确认服务仍在运行后重试。');
  }).finally(function () {
    submitting = false;
    submitBtn.disabled = false;
  });
}

