// 临时验证：201 已收到但正文未读完整/不可解析时的页面行为。验证后删除。
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { execFile, spawn } from 'node:child_process';
import { mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';
import net from 'node:net';
import puppeteer from 'puppeteer-core';

const repoRoot = import.meta.dirname;
const chromePath = process.env.CHROME_PATH || '/usr/bin/google-chrome';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let serverBin, browser;

const SEED_ALPHA =
  '{"id":"seed-alpha","name":"晨间飞行棋","game":"ludo","capacity":4,"turnSeconds":30,' +
  '"status":"playing","visibility":"public","createdAt":"2026-01-01T08:00:00Z"}';
const SEED_BETA =
  '{"id":"seed-beta","name":"午夜五子棋","game":"gomoku","capacity":2,"turnSeconds":0,' +
  '"status":"waiting","visibility":"public","createdAt":"2026-01-02T23:00:00Z"}';

before(async () => {
  const dir = await mkdtemp(path.join(tmpdir(), 'score-arena-uibin-'));
  serverBin = path.join(dir, 'score-arena');
  await promisify(execFile)('go', ['build', '-o', serverBin, '.'], { cwd: repoRoot });
  browser = await puppeteer.launch({
    executablePath: chromePath,
    headless: true,
    args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
  });
});
after(async () => {
  if (browser) await browser.close();
  if (serverBin) await rm(path.dirname(serverBin), { recursive: true, force: true });
});

function startServer(t, dataDir) {
  const proc = spawn(serverBin, ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
    { stdio: ['ignore', 'pipe', 'inherit'] });
  t.after(() => proc.kill('SIGKILL'));
  return new Promise((resolve, reject) => {
    let buf = '';
    const timer = setTimeout(() => reject(new Error('timeout')), 15000);
    proc.stdout.on('data', (c) => {
      buf += c.toString();
      const m = buf.match(/listening on (http:\/\/\S+)/);
      if (m) { clearTimeout(timer); resolve(m[1]); }
    });
  });
}

// 原始 TCP 服务：收到请求后回 201 状态行与极少量正文即断连，
// 模拟“状态行已收到、正文读取中断开”。
function startPartialServer(t) {
  return new Promise((resolve) => {
    const server = net.createServer((socket) => {
      socket.on('data', () => {
        socket.write('HTTP/1.1 201 Created\r\nContent-Type: application/json; charset=utf-8\r\n' +
          'Content-Length: 200\r\nConnection: close\r\n\r\n{"id":"ab');
        socket.destroy();
      });
    });
    server.listen(0, '127.0.0.1', () => {
      t.after(() => server.close());
      resolve(server.address().port);
    });
  });
}

async function setupPage(t) {
  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
  t.after(() => rm(dataDir, { recursive: true, force: true }));
  await writeFile(path.join(dataDir, 'rooms.json'), '[\n' + SEED_ALPHA + ',\n' + SEED_BETA + '\n]\n');
  const baseURL = await startServer(t, dataDir);
  const page = await browser.newPage();
  t.after(() => page.close());
  await page.goto(baseURL, { waitUntil: 'load' });
  await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 2,
    { timeout: 10000 });
  return { page, baseURL };
}

const readForm = (page) => page.evaluate(() => ({
  name: document.getElementById('name').value,
  game: document.getElementById('game').value,
  capacity: document.getElementById('capacity').value,
  capacityDisabled: document.getElementById('capacity').disabled,
  turnSeconds: document.getElementById('turnSeconds').value,
  submitDisabled: document.getElementById('submit').disabled,
}));
const readMsg = (page) => page.evaluate(() => {
  const el = document.getElementById('form-msg');
  return { className: el.className, text: el.textContent };
});
const readRows = (page) => page.$$eval('#list-area table tbody tr', (trs) =>
  trs.map((tr) => [...tr.querySelectorAll('td')].slice(0, 2).map((td) => td.textContent)));
async function serverRooms(baseURL) {
  const res = await fetch(baseURL + '/api/rooms');
  return (await res.json()).rooms;
}
async function fillLudo(page) {
  await page.type('#name', '  结果未确认的房间  ');
  await page.select('#game', 'ludo');
  await page.waitForFunction(() => !document.getElementById('capacity').disabled, { timeout: 5000 });
  await page.select('#capacity', '4');
  await page.type('#turnSeconds', '60');
}

function assertAmbiguous(msg) {
  assert.ok(msg.className.includes('error'), '应以错误样式提示，实际 class: ' + msg.className);
  assert.ok(msg.text.includes('未能确认'), '应说明创建结果未能确认，实际: ' + msg.text);
  assert.ok(msg.text.includes('可能已经保存'), '应提醒房间可能已经保存');
  assert.ok(msg.text.includes('刷新'), '应提醒先刷新页面查看列表');
  assert.ok(!msg.text.includes('编号：'), '不得显示成功编号');
  assert.ok(!msg.text.includes('undefined'), '不得出现 undefined');
  assert.ok(!msg.text.includes('已创建，编号'), '不得显示成功文案');
  assert.ok(!/创建失败/.test(msg.text), '不能承诺创建失败');
}

async function scenario(t, mode) {
  const { page, baseURL } = await setupPage(t);
  const initialRows = await readRows(page);

  let partialPort = null;
  if (mode === 'disconnect') partialPort = await startPartialServer(t);

  const counts = { POST: 0, GET: 0 };
  let ambiguousHandled = 0;
  await page.setRequestInterception(true);
  page.on('request', (req) => {
    const isPost = req.method() === 'POST' && req.url().endsWith('/api/rooms');
    const isGet = req.method() === 'GET' && req.url().endsWith('/api/rooms');
    if (isPost) counts.POST++;
    if (isGet) counts.GET++;
    if (isPost && ambiguousHandled === 0) {
      ambiguousHandled++;
      if (mode === 'empty') {
        req.respond({ status: 201, contentType: 'application/json; charset=utf-8', body: '' });
      } else if (mode === 'truncated') {
        req.respond({ status: 201, contentType: 'application/json; charset=utf-8', body: '{"id":"' });
      } else if (mode === 'notobject') {
        req.respond({ status: 201, contentType: 'application/json; charset=utf-8', body: '"oops"' });
      } else if (mode === 'noid') {
        req.respond({ status: 201, contentType: 'application/json; charset=utf-8',
          body: JSON.stringify({ name: 'x' }) });
      } else if (mode === 'disconnect') {
        req.continue({ url: 'http://127.0.0.1:' + partialPort + '/create' });
      } else {
        req.continue();
      }
      return;
    }
    req.continue();
  });

  await fillLudo(page);
  const getsBeforePost = counts.GET;
  await page.click('#submit');
  await page.waitForFunction(() => document.getElementById('form-msg').classList.contains('error'),
    { timeout: 10000 });

  const msg = await readMsg(page);
  assertAmbiguous(msg);

  // 四项按页面实际填写保留（含名称首尾空白），人数仍可用，按钮恢复。
  assert.deepEqual(await readForm(page), {
    name: '  结果未确认的房间  ',
    game: 'ludo', capacity: '4', capacityDisabled: false,
    turnSeconds: '60', submitDisabled: false,
  }, '未确认后应保留全部实际填写并恢复按钮');

  // 列表原样保留，不自动刷新（POST 之后没有新的 GET），不显示加载失败/空提示。
  assert.deepEqual(await readRows(page), initialRows, '已有列表内容与次序必须保留');
  await sleep(300);
  assert.equal(counts.GET, getsBeforePost, '未确认时不得自动刷新列表');
  assert.equal(counts.POST, 1, '不得自动重发创建请求');

  // 服务端没有新记录（请求被拦截/导向假服务）。
  assert.equal((await serverRooms(baseURL)).length, 2, '服务端不应出现记录变化');

  // 用户决定重新提交：第二次 POST 放行到真实服务，正常成功。
  await page.click('#submit');
  await page.waitForFunction(() => document.getElementById('form-msg').classList.contains('ok'),
    { timeout: 10000 });
  const msg2 = await readMsg(page);
  assert.ok(msg2.text.startsWith('房间已创建，编号：'), '重新提交应正常成功，实际: ' + msg2.text);
  assert.equal(counts.POST, 2, '重新提交应只发出一次新请求');
  assert.deepEqual(await readForm(page), {
    name: '', game: '', capacity: '', capacityDisabled: true,
    turnSeconds: '', submitDisabled: false,
  }, '重新提交成功后按现有约定复位表单');
  const rooms = await serverRooms(baseURL);
  assert.equal(rooms.length, 3);
  assert.equal(rooms[2].name, '结果未确认的房间');
}

